      pairs.push([name(a), name(b)]);
      rates.push(val[a] / val[b]);
    }
    for (let i = 0; i < q; i++) queries.push([name(r.int(0, pool)), name(r.int(0, pool))]);
    return [pairs, rates, queries];
  }

