function exchangeRates(pairs: string[][], rates: number[], queries: string[][]): number[] {
  const g = new Map<string, [string, number][]>();
  const link = (a: string, b: string, v: number) => {
    if (!g.has(a)) g.set(a, []);
    g.get(a)!.push([b, v]);
  };
  pairs.forEach(([a, b], i) => { link(a, b, rates[i]); link(b, a, 1 / rates[i]); });
  return queries.map(([c, d]) => {
    if (!g.has(c) || !g.has(d)) return -1;
    const seen = new Set([c]);
    const stack: [string, number][] = [[c, 1]];
    while (stack.length) {
      const [node, prod] = stack.pop()!;
      if (node === d) return prod;
      for (const [next, w] of g.get(node)!) {
        if (!seen.has(next)) { seen.add(next); stack.push([next, prod * w]); }
      }
    }
    return -1;
  });
}

