class Solution:
    def exchangeRates(self, pairs: List[List[str]], rates: List[float], queries: List[List[str]]) -> List[float]:
        g = defaultdict(list)
        for (a, b), v in zip(pairs, rates):
            g[a].append((b, v))
            g[b].append((a, 1 / v))
        out = []
        for c, d in queries:
            if c not in g or d not in g:
                out.append(-1.0)
                continue
            seen, stack, ans = {c}, [(c, 1.0)], -1.0
            while stack:
                node, prod = stack.pop()
                if node == d:
                    ans = prod
                    break
                for nxt, w in g[node]:
                    if nxt not in seen:
                        seen.add(nxt)
                        stack.append((nxt, prod * w))
            out.append(ans)
        return out

