function exchangeRates(pairs: string[][], rates: number[], queries: string[][]): number[] {
  const parent = new Map<string, string>();
  const worth = new Map<string, number>(); // 1 unit of x = worth(x) units of parent(x)
  const find = (x: string): string => {
    const p = parent.get(x)!;
    if (p === x) return x;
    const root = find(p);
    worth.set(x, worth.get(x)! * worth.get(p)!);
    parent.set(x, root);
    return root;
  };
  const add = (x: string) => { if (!parent.has(x)) { parent.set(x, x); worth.set(x, 1); } };
  pairs.forEach(([a, b], i) => {
    add(a); add(b);
    const ra = find(a), rb = find(b);
    if (ra === rb) return;
    // 1 a = rates[i] b, so 1 ra = rates[i] * worth(b) / worth(a) units of rb
    parent.set(ra, rb);
    worth.set(ra, rates[i] * worth.get(b)! / worth.get(a)!);
  });
  return queries.map(([c, d]) => {
    if (!parent.has(c) || !parent.has(d) || find(c) !== find(d)) return -1;
    return worth.get(c)! / worth.get(d)!;
  });
}

