class Solution:
    def exchangeRates(self, pairs: List[List[str]], rates: List[float], queries: List[List[str]]) -> List[float]:
        parent, worth = {}, {}  # 1 unit of x = worth[x] units of parent[x]

        def find(x):
            path = []
            while parent[x] != x:
                path.append(x)
                x = parent[x]
            # compress from the node nearest the root outwards
            for y in reversed(path):
                p = parent[y]
                if p != x:
                    worth[y] *= worth[p]
                parent[y] = x
            return x

        for (a, b), v in zip(pairs, rates):
            for x in (a, b):
                if x not in parent:
                    parent[x], worth[x] = x, 1.0
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                worth[ra] = v * worth[b] / worth[a]
        out = []
        for c, d in queries:
            if c not in parent or d not in parent or find(c) != find(d):
                out.append(-1.0)
            else:
                out.append(worth[c] / worth[d])
        return out

